"""Recursive-descent parser for minilang.

Produces an AST built from simple dataclasses; parsing never evaluates
anything (e.g. ``parse("1 / 0")`` succeeds).
"""

from dataclasses import dataclass, field
from typing import Any, List

from .errors import ParseError
from .lexer import tokenize

_COMPARISON_OPS = ("==", "!=", "<", "<=", ">", ">=")


@dataclass
class NumberNode:
    value: float
    position: int


@dataclass
class StringNode:
    value: str
    position: int


@dataclass
class BoolNode:
    value: bool
    position: int


@dataclass
class IdentNode:
    name: str
    position: int


@dataclass
class CallNode:
    name: str
    args: List[Any] = field(default_factory=list)
    position: int = 0


@dataclass
class UnaryMinusNode:
    operand: Any
    position: int


@dataclass
class NotNode:
    operand: Any
    position: int


@dataclass
class AndNode:
    left: Any
    right: Any
    position: int


@dataclass
class OrNode:
    left: Any
    right: Any
    position: int


@dataclass
class BinOpNode:
    op: str
    left: Any
    right: Any
    position: int


class _Parser:
    def __init__(self, tokens, source_len):
        self.tokens = tokens
        self.pos = 0
        self.source_len = source_len

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def at_end(self):
        return self.pos >= len(self.tokens)

    def eof_position(self):
        return self.source_len

    def is_op(self, tok, value):
        return tok is not None and tok.kind == "OP" and tok.value == value

    def is_op_in(self, tok, values):
        return tok is not None and tok.kind == "OP" and tok.value in values

    def is_keyword(self, tok, value):
        return tok is not None and tok.kind == "KEYWORD" and tok.value == value

    # expr := or_expr
    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        left = self.parse_and()
        while self.is_keyword(self.peek(), "or"):
            self.advance()
            right = self.parse_and()
            left = OrNode(left, right, left.position)
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.is_keyword(self.peek(), "and"):
            self.advance()
            right = self.parse_not()
            left = AndNode(left, right, left.position)
        return left

    def parse_not(self):
        tok = self.peek()
        if self.is_keyword(tok, "not"):
            self.advance()
            operand = self.parse_not()
            return NotNode(operand, tok.position)
        return self.parse_comparison()

    def parse_comparison(self):
        left = self.parse_additive()
        tok = self.peek()
        if self.is_op_in(tok, _COMPARISON_OPS):
            op = tok.value
            pos = tok.position
            self.advance()
            right = self.parse_additive()
            node = BinOpNode(op, left, right, pos)
            tok2 = self.peek()
            if self.is_op_in(tok2, _COMPARISON_OPS):
                raise ParseError(
                    "comparison operators are non-associative", tok2.position
                )
            return node
        return left

    def parse_additive(self):
        left = self.parse_multiplicative()
        while True:
            tok = self.peek()
            if self.is_op_in(tok, ("+", "-")):
                self.advance()
                right = self.parse_multiplicative()
                left = BinOpNode(tok.value, left, right, tok.position)
            else:
                break
        return left

    def parse_multiplicative(self):
        left = self.parse_unary()
        while True:
            tok = self.peek()
            if self.is_op_in(tok, ("*", "/", "%")):
                self.advance()
                right = self.parse_unary()
                left = BinOpNode(tok.value, left, right, tok.position)
            else:
                break
        return left

    def parse_unary(self):
        tok = self.peek()
        if self.is_op(tok, "-"):
            self.advance()
            operand = self.parse_unary()
            return UnaryMinusNode(operand, tok.position)
        return self.parse_power()

    def parse_power(self):
        left = self.parse_primary()
        tok = self.peek()
        if self.is_op(tok, "^"):
            self.advance()
            right = self.parse_unary()
            return BinOpNode("^", left, right, tok.position)
        return left

    def parse_primary(self):
        tok = self.peek()
        if tok is None:
            raise ParseError("unexpected end of input", self.eof_position())

        if tok.kind == "NUMBER":
            self.advance()
            return NumberNode(tok.value, tok.position)

        if tok.kind == "STRING":
            self.advance()
            return StringNode(tok.value, tok.position)

        if tok.kind == "KEYWORD" and tok.value in ("true", "false"):
            self.advance()
            return BoolNode(tok.value == "true", tok.position)

        if tok.kind == "IDENT":
            self.advance()
            nxt = self.peek()
            if self.is_op(nxt, "("):
                self.advance()
                args = []
                if not self.is_op(self.peek(), ")"):
                    args.append(self.parse_expr())
                    while self.is_op(self.peek(), ","):
                        self.advance()
                        args.append(self.parse_expr())
                if not self.is_op(self.peek(), ")"):
                    p = self.peek()
                    pos = p.position if p is not None else self.eof_position()
                    raise ParseError("expected ')'", pos)
                self.advance()
                return CallNode(tok.value, args, tok.position)
            return IdentNode(tok.value, tok.position)

        if self.is_op(tok, "("):
            self.advance()
            node = self.parse_expr()
            if not self.is_op(self.peek(), ")"):
                p = self.peek()
                pos = p.position if p is not None else self.eof_position()
                raise ParseError("expected ')'", pos)
            self.advance()
            return node

        raise ParseError(f"unexpected token: {tok.value!r}", tok.position)


def parse(source: str):
    tokens = tokenize(source)
    if not tokens:
        raise ParseError("empty expression", 0)
    parser = _Parser(tokens, len(source))
    node = parser.parse_expr()
    if not parser.at_end():
        tok = parser.peek()
        raise ParseError("unexpected trailing input", tok.position)
    return node

"""Evaluator for minilang ASTs."""

import math

from .errors import EvalError
from .parser import (
    AndNode,
    BinOpNode,
    BoolNode,
    CallNode,
    IdentNode,
    NotNode,
    NumberNode,
    OrNode,
    StringNode,
    UnaryMinusNode,
)

_COMPARISON_OPS = ("<", "<=", ">", ">=")


def format_number(x: float) -> str:
    """Format a number the way the REPL displays it (rule 33)."""
    if math.isfinite(x) and x == int(x):
        return str(int(x))
    return repr(x)


def format_string(s: str) -> str:
    """Format a string with surrounding quotes and re-escaped contents."""
    out = ['"']
    for ch in s:
        if ch == "\\":
            out.append("\\\\")
        elif ch == '"':
            out.append('\\"')
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\t":
            out.append("\\t")
        elif ch == "\r":
            out.append("\\r")
        else:
            out.append(ch)
    out.append('"')
    return "".join(out)


def format_value(v) -> str:
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, float):
        return format_number(v)
    if isinstance(v, str):
        return format_string(v)
    raise TypeError(f"cannot format value: {v!r}")


def _values_equal(a, b) -> bool:
    if type(a) is not type(b):
        return False
    return a == b


def eval_node(node, env: dict):
    if isinstance(node, NumberNode):
        return node.value
    if isinstance(node, StringNode):
        return node.value
    if isinstance(node, BoolNode):
        return node.value

    if isinstance(node, IdentNode):
        if node.name not in env:
            raise EvalError(f"undefined variable: {node.name}")
        val = env[node.name]
        if not isinstance(val, (float, str, bool)) or (
            isinstance(val, int) and not isinstance(val, (bool, float))
        ):
            raise EvalError(f"unsupported value for {node.name}: {val!r}")
        return val

    if isinstance(node, UnaryMinusNode):
        val = eval_node(node.operand, env)
        if not isinstance(val, float):
            raise EvalError("unary '-' requires a number")
        return -val

    if isinstance(node, NotNode):
        val = eval_node(node.operand, env)
        if not isinstance(val, bool):
            raise EvalError("'not' requires a boolean")
        return not val

    if isinstance(node, AndNode):
        left = eval_node(node.left, env)
        if not isinstance(left, bool):
            raise EvalError("'and' requires boolean operands")
        if left is False:
            return False
        right = eval_node(node.right, env)
        if not isinstance(right, bool):
            raise EvalError("'and' requires boolean operands")
        return right

    if isinstance(node, OrNode):
        left = eval_node(node.left, env)
        if not isinstance(left, bool):
            raise EvalError("'or' requires boolean operands")
        if left is True:
            return True
        right = eval_node(node.right, env)
        if not isinstance(right, bool):
            raise EvalError("'or' requires boolean operands")
        return right

    if isinstance(node, BinOpNode):
        return _eval_binop(node, env)

    if isinstance(node, CallNode):
        return _eval_call(node, env)

    raise EvalError(f"cannot evaluate node: {node!r}")


def _is_number(v) -> bool:
    return isinstance(v, float)


def _eval_binop(node, env):
    op = node.op
    left = eval_node(node.left, env)
    right = eval_node(node.right, env)

    if op == "+":
        if _is_number(left) and _is_number(right):
            return left + right
        if isinstance(left, str) and isinstance(right, str):
            return left + right
        raise EvalError("'+' requires two numbers or two strings")

    if op in ("-", "*", "/", "%"):
        if not (_is_number(left) and _is_number(right)):
            raise EvalError(f"'{op}' requires two numbers")
        if op == "-":
            return left - right
        if op == "*":
            return left * right
        if op == "/":
            if right == 0:
                raise EvalError("division by zero")
            return left / right
        if op == "%":
            if right == 0:
                raise EvalError("modulo by zero")
            return math.fmod(left, right) if False else left % right

    if op == "^":
        if not (_is_number(left) and _is_number(right)):
            raise EvalError("'^' requires two numbers")
        try:
            result = left**right
        except OverflowError:
            raise EvalError("result too large")
        if isinstance(result, complex):
            raise EvalError("result is not a real number")
        if isinstance(result, float) and math.isnan(result):
            raise EvalError("result is not a real number")
        return float(result)

    if op == "==" or op == "!=":
        eq = _values_equal(left, right)
        return eq if op == "==" else not eq

    if op in _COMPARISON_OPS:
        if _is_number(left) and _is_number(right):
            pass
        elif isinstance(left, str) and isinstance(right, str):
            pass
        else:
            raise EvalError(f"'{op}' requires two numbers or two strings")
        if op == "<":
            return left < right
        if op == "<=":
            return left <= right
        if op == ">":
            return left > right
        if op == ">=":
            return left >= right

    raise EvalError(f"unknown operator: {op}")


def _eval_call(node, env):
    from .builtins import BUILTINS

    name = node.name

    if name == "if":
        if len(node.args) != 3:
            raise EvalError(f"if() takes 3 argument(s), got {len(node.args)}")
        cond = eval_node(node.args[0], env)
        if not isinstance(cond, bool):
            raise EvalError("if() condition must be a boolean")
        if cond:
            return eval_node(node.args[1], env)
        return eval_node(node.args[2], env)

    if name not in BUILTINS:
        raise EvalError(f"undefined function: {name}")

    args = [eval_node(a, env) for a in node.args]
    return BUILTINS[name](args)


def evaluate_ast(node, env: dict):
    return eval_node(node, env)

