"""Built-in functions for minilang.

Each entry in BUILTINS is a callable that receives a list of already
evaluated arguments and returns a minilang value (float/str/bool), raising
EvalError on arity or type violations. ``if`` is handled specially in the
evaluator because its arguments must be evaluated lazily.
"""

from .errors import EvalError
from .evaluator import format_number


def _arity_error(name, expected, got):
    raise EvalError(f"{name}() takes {expected} argument(s), got {got}")


def _check_number(name, value, index=None):
    if not isinstance(value, float):
        where = f" (argument {index})" if index is not None else ""
        raise EvalError(f"{name}(){where} requires a number")


def _check_string(name, value, index=None):
    if not isinstance(value, str):
        where = f" (argument {index})" if index is not None else ""
        raise EvalError(f"{name}(){where} requires a string")


def _builtin_abs(args):
    if len(args) != 1:
        _arity_error("abs", 1, len(args))
    _check_number("abs", args[0])
    return abs(args[0])


def _builtin_min(args):
    if len(args) < 1:
        raise EvalError(f"min() takes at least 1 argument(s), got {len(args)}")
    for a in args:
        _check_number("min", a)
    return min(args)


def _builtin_max(args):
    if len(args) < 1:
        raise EvalError(f"max() takes at least 1 argument(s), got {len(args)}")
    for a in args:
        _check_number("max", a)
    return max(args)


def _builtin_round(args):
    if len(args) == 1:
        _check_number("round", args[0])
        return float(round(args[0]))
    if len(args) == 2:
        _check_number("round", args[0])
        n = args[1]
        _check_number("round", n)
        if n != int(n):
            raise EvalError("round() second argument must be a whole number")
        return float(round(args[0], int(n)))
    raise EvalError(f"round() takes 1 or 2 argument(s), got {len(args)}")


def _builtin_len(args):
    if len(args) != 1:
        _arity_error("len", 1, len(args))
    _check_string("len", args[0])
    return float(len(args[0]))


def _builtin_upper(args):
    if len(args) != 1:
        _arity_error("upper", 1, len(args))
    _check_string("upper", args[0])
    return args[0].upper()


def _builtin_lower(args):
    if len(args) != 1:
        _arity_error("lower", 1, len(args))
    _check_string("lower", args[0])
    return args[0].lower()


def _builtin_str(args):
    if len(args) != 1:
        _arity_error("str", 1, len(args))
    v = args[0]
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, float):
        return format_number(v)
    if isinstance(v, str):
        return v
    raise EvalError(f"str() cannot format value: {v!r}")


def _builtin_num(args):
    if len(args) != 1:
        _arity_error("num", 1, len(args))
    _check_string("num", args[0])
    try:
        return float(args[0].strip())
    except ValueError:
        raise EvalError(f"num() cannot parse value: {args[0]!r}")


BUILTINS = {
    "abs": _builtin_abs,
    "min": _builtin_min,
    "max": _builtin_max,
    "round": _builtin_round,
    "len": _builtin_len,
    "upper": _builtin_upper,
    "lower": _builtin_lower,
    "str": _builtin_str,
    "num": _builtin_num,
}

"""minilang: a small expression language (lexer, parser, evaluator)."""

from .errors import EvalError, LexError, MiniLangError, ParseError
from .evaluator import evaluate_ast
from .lexer import tokenize as _tokenize
from .parser import parse as _parse

__all__ = [
    "tokenize",
    "parse",
    "evaluate",
    "MiniLangError",
    "LexError",
    "ParseError",
    "EvalError",
]


def tokenize(source: str) -> list:
    return _tokenize(source)


def parse(source: str):
    return _parse(source)


def evaluate(source: str, env: dict | None = None):
    ast = _parse(source)
    # Never mutate the caller's env: evaluate on a private copy.
    local_env = dict(env) if env else {}
    return evaluate_ast(ast, local_env)

"""REPL for minilang: ``python -m minilang``."""

import re
import sys

from .errors import MiniLangError
from .evaluator import evaluate_ast, format_value
from .parser import parse

_ASSIGN_RE = re.compile(
    r"^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=(?!=)(.*)$", re.DOTALL
)


def main():
    env: dict = {}
    for raw_line in sys.stdin:
        line = raw_line.rstrip("\n")
        stripped = line.strip()

        if stripped == "":
            continue

        if stripped == ":quit":
            sys.exit(0)

        if stripped == ":vars":
            for name in sorted(env):
                print(f"{name} = {format_value(env[name])}")
            continue

        m = _ASSIGN_RE.match(line)
        if m:
            ident, expr_src = m.groups()
            try:
                ast = parse(expr_src)
                value = evaluate_ast(ast, env)
            except MiniLangError as e:
                print(f"error: {e}")
                continue
            env[ident] = value
            continue

        try:
            ast = parse(line)
            value = evaluate_ast(ast, env)
        except MiniLangError as e:
            print(f"error: {e}")
            continue
        print(format_value(value))

    sys.exit(0)


if __name__ == "__main__":
    main()

"""Test suite for minilang."""

import subprocess
import sys

import pytest

from minilang import EvalError, LexError, ParseError, evaluate, parse, tokenize


# ---------------------------------------------------------------------------
# Lexing
# ---------------------------------------------------------------------------

def test_lex_numbers():
    toks = tokenize("123 1.5 .5 1e3 1.2e-4 2E+8")
    values = [t.value for t in toks]
    assert values == [123.0, 1.5, 0.5, 1000.0, 1.2e-4, 2e8]
